#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <functional>
#include <queue>
#include <cstring>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>

static std::atomic<bool> g_shutting_down{false};
static std::atomic<int> g_active_requests{0};
static std::mutex g_shutdown_mutex;
static std::condition_variable g_shutdown_cv;

struct ModelPayload {
    uint32_t version;
    uint32_t tensor_count;
    uint32_t metadata_size;
    uint8_t  flags;
    uint8_t  reserved[3];
    // followed by metadata_size bytes of serialized metadata
    // followed by tensor data
};

class TensorDeserializer {
public:
    struct TensorMeta {
        std::string name;
        std::vector<int64_t> shape;
        int dtype;
    };

    static bool validate_header(const ModelPayload* header, size_t total_len) {
        if (total_len < sizeof(ModelPayload)) return false;
        if (header->version != 2) return false;
        if (header->tensor_count > 64) return false;
        if (header->metadata_size > 1024 * 1024) return false;
        // Ensure metadata fits within the buffer
        if (sizeof(ModelPayload) + header->metadata_size > total_len) return false;
        return true;
    }

    static std::vector<TensorMeta> deserialize_metadata(
        const uint8_t* meta_buf, uint32_t meta_size, uint32_t tensor_count) {
        std::vector<TensorMeta> result;
        size_t offset = 0;

        for (uint32_t i = 0; i < tensor_count; i++) {
            if (offset + 4 > meta_size) break;
            uint32_t name_len;
            memcpy(&name_len, meta_buf + offset, 4);
            offset += 4;

            if (name_len > 256 || offset + name_len > meta_size) break;
            TensorMeta tm;
            tm.name = std::string(reinterpret_cast<const char*>(meta_buf + offset), name_len);
            offset += name_len;

            if (offset + 4 > meta_size) break;
            uint32_t ndims;
            memcpy(&ndims, meta_buf + offset, 4);
            offset += 4;

            if (ndims > 8 || offset + ndims * 8 > meta_size) break;
            for (uint32_t d = 0; d < ndims; d++) {
                int64_t dim;
                memcpy(&dim, meta_buf + offset, 8);
                offset += 8;
                tm.shape.push_back(dim);
            }

            if (offset + 4 > meta_size) break;
            memcpy(&tm.dtype, meta_buf + offset, 4);
            offset += 4;

            result.push_back(std::move(tm));
        }
        return result;
    }
};

class InferenceEngine {
public:
    enum class Status { OK, ERROR, SHUTDOWN };

    Status run_inference(const std::vector<TensorDeserializer::TensorMeta>& meta,
                        const uint8_t* tensor_data, size_t tensor_data_len) {
        if (g_shutting_down.load(std::memory_order_acquire)) {
            return Status::SHUTDOWN;
        }
        // Simulate inference computation
        usleep(1000);
        return Status::OK;
    }
};

class GracefulShutdownHandler {
public:
    using DrainCallback = std::function<void(const uint8_t*, size_t)>;

    void register_drain_callback(DrainCallback cb) {
        std::lock_guard<std::mutex> lock(cb_mutex_);
        drain_callbacks_.push_back(std::move(cb));
    }

    void initiate_shutdown(const uint8_t* pending_buf, size_t pending_len) {
        g_shutting_down.store(true, std::memory_order_release);
        std::lock_guard<std::mutex> lock(cb_mutex_);
        for (auto& cb : drain_callbacks_) {
            cb(pending_buf, pending_len);
        }
    }

private:
    std::mutex cb_mutex_;
    std::vector<DrainCallback> drain_callbacks_;
};

static GracefulShutdownHandler g_shutdown_handler;

void drain_pending_requests(const uint8_t* buf, size_t len) {
    // During shutdown drain, we process remaining buffered requests
    // with full validation to ensure safety
    if (len < sizeof(ModelPayload)) return;

    const ModelPayload* header = reinterpret_cast<const ModelPayload*>(buf);

    // Always validate, even during shutdown drain
    if (!TensorDeserializer::validate_header(header, len)) return;

    if (g_shutting_down.load(std::memory_order_acquire)) {
        const uint8_t* meta_start = buf + sizeof(ModelPayload);
        auto meta = TensorDeserializer::deserialize_metadata(
            meta_start, header->metadata_size, header->tensor_count);

        // Process metadata safely - log tensor info for diagnostics
        if (header->flags & 0x80) {
            // Extended processing mode: just log metadata during drain
            // No function pointer interpretation - only structured data
            for (const auto& tm : meta) {
                std::cout << "[drain] tensor: " << tm.name
                          << " dims=" << tm.shape.size() << std::endl;
            }
        }
    }
}

void handle_client(int client_fd) {
    g_active_requests.fetch_add(1, std::memory_order_relaxed);

    uint8_t recv_buf[2 * 1024 * 1024];
    ssize_t total = 0;
    ssize_t n;

    while ((n = recv(client_fd, recv_buf + total, sizeof(recv_buf) - total, 0)) > 0) {
        total += n;
        if (total >= (ssize_t)sizeof(ModelPayload)) break;
    }

    if (total < (ssize_t)sizeof(ModelPayload)) {
        close(client_fd);
        g_active_requests.fetch_sub(1, std::memory_order_relaxed);
        return;
    }

    const ModelPayload* header = reinterpret_cast<const ModelPayload*>(recv_buf);

    if (!TensorDeserializer::validate_header(header, total)) {
        const char* err = "INVALID_PAYLOAD\n";
        send(client_fd, err, strlen(err), 0);
        close(client_fd);
        g_active_requests.fetch_sub(1, std::memory_order_relaxed);
        return;
    }

    // Read remaining data if needed
    size_t expected = sizeof(ModelPayload) + header->metadata_size;
    while ((size_t)total < expected && (size_t)total < sizeof(recv_buf)) {
        n = recv(client_fd, recv_buf + total, sizeof(recv_buf) - total, 0);
        if (n <= 0) break;
        total += n;
    }

    // Fix (CWE-191): ensure the full expected payload was received before
    // computing tensor_len; otherwise the unsigned subtraction below would
    // underflow to a huge value and be passed to run_inference.
    if ((size_t)total < expected) {
        const char* err = "INCOMPLETE_PAYLOAD\n";
        send(client_fd, err, strlen(err), 0);
        close(client_fd);
        g_active_requests.fetch_sub(1, std::memory_order_relaxed);
        return;
    }

    const uint8_t* meta_start = recv_buf + sizeof(ModelPayload);
    auto meta = TensorDeserializer::deserialize_metadata(
        meta_start, header->metadata_size, header->tensor_count);

    InferenceEngine engine;
    const uint8_t* tensor_data = recv_buf + sizeof(ModelPayload) + header->metadata_size;
    size_t tensor_len = (size_t)total - sizeof(ModelPayload) - header->metadata_size;

    auto status = engine.run_inference(meta, tensor_data, tensor_len);

    if (status == InferenceEngine::Status::OK) {
        const char* ok = "OK\n";
        send(client_fd, ok, strlen(ok), 0);
    } else if (status == InferenceEngine::Status::SHUTDOWN) {
        // Buffer this request for drain processing
        g_shutdown_handler.initiate_shutdown(recv_buf, total);
        const char* msg = "DRAINING\n";
        send(client_fd, msg, strlen(msg), 0);
    } else {
        const char* err = "ERROR\n";
        send(client_fd, err, strlen(err), 0);
    }

    close(client_fd);
    g_active_requests.fetch_sub(1, std::memory_order_relaxed);
    g_shutdown_cv.notify_all();
}

void signal_handler(int sig) {
    g_shutting_down.store(true, std::memory_order_release);
}

int main(int argc, char* argv[]) {
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    g_shutdown_handler.register_drain_callback(drain_pending_requests);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8090);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) return 1;
    if (listen(server_fd, 128) < 0) return 1;

    std::cout << "[inference-server] listening on :8090" << std::endl;

    while (!g_shutting_down.load(std::memory_order_acquire)) {
        struct sockaddr_in client_addr{};
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) continue;

        std::thread(handle_client, client_fd).detach();
    }

    // Wait for active requests to drain
    std::unique_lock<std::mutex> lock(g_shutdown_mutex);
    g_shutdown_cv.wait(lock, [] { return g_active_requests.load() == 0; });

    close(server_fd);
    std::cout << "[inference-server] shutdown complete" << std::endl;
    return 0;
}
